//! 🧩️ Source-qualified Drawing JSON visits original value leaves without lowering or copying a complete scene.
use super::{TypedJsonCursor,JsonStringWriteCursor,finite_json_number,MAX_LAYOUT_EXPORT_PACKAGE_FRAGMENT_BYTES};
use semio_s_artifact_layout_layout_model::{DrawingSourceAddress,drawing_child_at,snapshot::LayoutSnapshot};
use semio_framework_value::{DslValue,Number};
#[derive(Clone,Debug)]
enum Task {Static(&'static[u8]),Handle(u8,JsonStringWriteCursor),Value(Vec<usize>),Array(Vec<usize>,usize),Object(Vec<usize>,usize),Bytes(Vec<usize>,usize),Text(Vec<usize>,Option<usize>,JsonStringWriteCursor)}
/// 🧵️ One captured child address and bounded pending ancestry retain no content copies.
#[derive(Clone,Debug)]
pub struct ChildJsonCursor {source:DrawingSourceAddress,tasks:Vec<Task>,bytes:usize}
impl ChildJsonCursor {
 pub fn new(source:DrawingSourceAddress)->Self{Self{source,tasks:vec![Task::Static(b"}"),Task::Value(Vec::new()),Task::Static(b",\"content\":"),Task::Static(b"}}}"),Task::Handle(4,Default::default()),Task::Static(b",\"subset\":"),Task::Handle(3,Default::default()),Task::Static(b",\"standard\":"),Task::Handle(2,Default::default()),Task::Static(b",\"dialect\":{\"artifactKind\":"),Task::Handle(1,Default::default()),Task::Static(b",\"target\":{\"artifactId\":"),Task::Handle(0,Default::default()),Task::Static(b"{\"handle\":{\"childId\":")],bytes:0}}
 pub fn owned_bytes(&self)->usize{self.tasks.capacity()*std::mem::size_of::<Task>()+self.tasks.iter().map(|task|match task{Task::Value(path)|Task::Array(path,_)|Task::Object(path,_)|Task::Bytes(path,_)|Task::Text(path,_,_)=>path.capacity()*std::mem::size_of::<usize>(),_=>0}).sum::<usize>()}
 fn value<'a>(&self,snapshot:&'a LayoutSnapshot,path:&[usize])->Result<&'a DslValue,String>{let child=drawing_child_at(snapshot,self.source).map_err(|e|e.to_string())?.ok_or("layout-export-child-source")?;let mut value=&child.content;for index in path{value=match value{DslValue::Array(items)=>items.get(*index),DslValue::Object(members)=>members.get(*index).map(|(_,value)|value),_=>None}.ok_or("layout-export-child-path")?;}Ok(value)}
 pub fn advance(&mut self,snapshot:&LayoutSnapshot)->Result<(Vec<u8>,bool),String>{let Some(task)=self.tasks.pop()else{return Ok((Vec::new(),true))};let mut output=Vec::new();match task{
 Task::Static(bytes)=>output.extend_from_slice(bytes),
 Task::Handle(field,mut cursor)=>{let child=drawing_child_at(snapshot,self.source).map_err(|e|e.to_string())?.ok_or("layout-export-child-source")?;let h=&child.handle;let text=match field{0=>h.child_id.as_str(),1=>h.target.artifact_id.as_str(),2=>h.target.dialect.artifact_kind.as_str(),3=>h.target.dialect.standard.as_str(),4=>h.target.dialect.subset.as_str(),_=>return Err("layout-export-child-handle".into())};let(bytes,done)=TypedJsonCursor::escaped_string_step(text,&mut cursor);output=bytes;if !done{self.tasks.push(Task::Handle(field,cursor));}},
 Task::Value(path)=>match self.value(snapshot,&path)?{DslValue::Null=>output.extend_from_slice(b"null"),DslValue::Bool(v)=>output.extend_from_slice(if *v{b"true"}else{b"false"}),DslValue::Number(Number::Float(v))=>output=finite_json_number(*v)?,DslValue::Number(Number::Int(v))=>output.extend_from_slice(v.to_string().as_bytes()),DslValue::Number(Number::UInt(v))=>output.extend_from_slice(v.to_string().as_bytes()),DslValue::String(_)=>self.tasks.push(Task::Text(path,None,Default::default())),DslValue::Array(_)=>{output.push(b'[');self.tasks.push(Task::Array(path,0));},DslValue::Object(_)=>{output.push(b'{');self.tasks.push(Task::Object(path,0));},DslValue::Bytes(_)=>{output.push(b'[');self.tasks.push(Task::Bytes(path,0));}},
 Task::Array(path,index)=>{let DslValue::Array(items)=self.value(snapshot,&path)?else{return Err("layout-export-child-array".into())};if index==items.len(){output.push(b']')}else{if index>0{output.push(b',')}let mut child=path.clone();child.push(index);self.tasks.extend([Task::Array(path,index+1),Task::Value(child)]);}},
 Task::Object(path,index)=>{let DslValue::Object(members)=self.value(snapshot,&path)?else{return Err("layout-export-child-object".into())};if index==members.len(){output.push(b'}')}else{if index>0{output.push(b',')}let mut child=path.clone();child.push(index);self.tasks.extend([Task::Object(path.clone(),index+1),Task::Value(child),Task::Static(b":"),Task::Text(path,Some(index),Default::default())]);}},
 Task::Bytes(path,index)=>{let DslValue::Bytes(bytes)=self.value(snapshot,&path)?else{return Err("layout-export-child-bytes".into())};if index==bytes.len(){output.push(b']')}else{if index>0{output.push(b',')}output.extend_from_slice(bytes[index].to_string().as_bytes());self.tasks.push(Task::Bytes(path,index+1));}},
 Task::Text(path,member,mut cursor)=>{let text=match(self.value(snapshot,&path)?,member){(DslValue::String(text),None)=>text.as_str(),(DslValue::Object(members),Some(index))=>members.get(index).map(|(name,_)|name.as_str()).ok_or("layout-export-child-key")?,_=>return Err("layout-export-child-text".into())};let(bytes,done)=TypedJsonCursor::escaped_string_step(text,&mut cursor);output=bytes;if !done{self.tasks.push(Task::Text(path,member,cursor));}}
 }self.bytes=self.bytes.checked_add(output.len()).ok_or("layout-export-json-byte-limit")?;if self.bytes>MAX_LAYOUT_EXPORT_PACKAGE_FRAGMENT_BYTES{return Err("layout-export-json-byte-limit".into())}Ok((output,self.tasks.is_empty()))}
}
